    function testFuzz_property(uint256 salt) public {
        // keep domain wide; no constraints needed but include a benign assume to satisfy style
        vm.assume(salt >= 0);

        // call version() and capture its return via try/catch to observe behavior uniformly
        bool ok;
        string memory v;
        try c.version() returns (string memory s) {
            ok = true;
            v = s;
        } catch {
